// Flatten PRH company events into one row per event for Google Sheets.
// Company-level data only (business ID, name, form, industry, municipality); no personal data.
return $input.all().map(i => i.json).filter(e => e.eventKey).map(e => ({ json: {
  eventKey: e.eventKey,
  eventDate: e.eventDate,
  eventType: e.eventLabel || e.eventType,
  businessId: e.businessId,
  companyName: e.companyName,
  companyForm: e.companyForm ? e.companyForm.en : '',
  industryTOL2008: e.mainBusinessLine ? `${e.mainBusinessLine.tol2008} ${e.mainBusinessLine.en || ''}`.trim() : '',
  city: e.location ? e.location.city : '',
  website: e.website || '',
  sourceApiUrl: e.sourceApiUrl,
  attribution: e.attribution,
}}));
